			/**
			 * step 변경과 step에 따른 아코디언 visible 처리
			 * @param {Number} pnStep step
			 * @param {Boolean} pbReadOnly readOnly
			 */
			function setStepAcdAttr(pnStep, pbReadOnly) {
			    var vcStepProg = app.lookup("cmnStepProgress");
			    var vbReadOnly = pbReadOnly != null ? pbReadOnly : true;
			    
			    var vcGrpData = app.lookup("grpData");
			    var vsAcdId = "acdStep" + pnStep;
			    
			    vcGrpData.getChildren().forEach(function(ctrl) {
			        if (ctrl instanceof cpr.controls.Accordion) {
			            if (ctrl.id == vsAcdId) {
			                ctrl.visible = true;                
			            } else {
			                ctrl.visible = false;                
			            }
			            
			            ctrl.readOnly = pbReadOnly;
			        }
			    });
			    
			    vcStepProg.step = pnStep;
			}

			/**
			 * 상세 페이지 CRUD 권한 처리 
			 * @param {"CREATE" | "READ" | "UPDATE"} psType CRUD Type
			 */
			function setDtlCrud(psType) {

			    
			    if (psType == "READ") {
			        
			        util.Control.setReadOnly(app, true, ["grpData"]);
			        util.Control.setVisible(app, false, ["btnSave", "btnRestore"]);
			        util.Control.setVisible(app, true, ["btnUpdate", "btnDelete"]);
			        
			        app.lookup("ds3").clearFilter();
			        app.lookup("dsFamInfo").clearFilter();
			        app.lookup("dsList17").clearFilter();
			        
			        msCrudType = "READ";
			    } else {
			        
			        if (psType == "CREATE") {
			            app.lookup("dmDefInfo").clear();
			            // 임시 데이터셋 클리어
			            app.lookup("ds3").setFilter("column1 == '" + "1" +"'");
			            app.lookup("dsFamInfo").setFilter("column1 == '" + "1" +"'");
			            app.lookup("dsList17").setFilter("column1 == '" + "1" +"'");
			            
			            msCrudType = "CREATE";
			            
			        } else if (psType == "UPDATE") {            
			            msCrudType = "UPDATE";
			        }
			                
			        util.Control.setReadOnly(app, false, ["grpData"]);
			        util.Control.setVisible(app, true, ["btnSave", "btnRestore"]);
			        util.Control.setVisible(app, false, ["btnUpdate", "btnDelete"]);
			    }
			    
			    util.Control.redraw(app, "grpData");
			}


